beforeSaveCustomScript:
// ============================================================
// AUTO-FILL SUBREQUESTTYPE FROM CATEGORY FIELDS
// ============================================================

// Check which field has a value and copy it to subRequestType
if (gA != null && gA != '') {
    subRequestType = gA;
} else if (rM != null && rM != '') {
    subRequestType = rM;
} else if (gCA != null && gCA != '') {
    subRequestType = gCA;
} else {
    // If none have values, keep subRequestType as is or clear it
    // subRequestType = null;
}


// ============================================================
// DECISION D EMPLOYEE TO STATUS MAPPING
// ============================================================


if (requestType == 'Gestion des congés et absences') {
    if (dcisionDemp == 'Accepté') {
        status = 'accepted';
    } else if (dcisionDemp == 'Refusé') {
        status = 'rejected';
    } else if (dcisionDemp == 'pending') {
        status = 'pending';
    } else if (dcisionDemp == 'Reporté') {
        if (reportuneDateUltrieure != null) {
            status = string\concatenate('Reporté: ', datetime\format(reportuneDateUltrieure, 'YYYY-MM-DD'));
        } else {
            status = 'Reporté';
        }
    }
}
